<h4 class="fw-bold mb-4">Logs de Erro</h4><div class="card"><table class="table mb-0"><thead><tr><th>Data</th><th>Nível</th><th>Mensagem</th><th>Arquivo</th></tr></thead><tbody><?php foreach($logs as $l): ?><tr><td><?= htmlspecialchars($l['created_at'] ?? '') ?></td><td><?= htmlspecialchars($l['level'] ?? '') ?></td><td><?= htmlspecialchars($l['message'] ?? '') ?></td><td><?= htmlspecialchars(($l['file'] ?? '').':'.($l['line'] ?? '')) ?></td></tr><?php endforeach; ?></tbody></table></div>